    /** M3Automaton.step#1 PERF; oracle: AutomatonOracle.transitions(linear-scan). */
    static M3AtomPerf.Batch step() throws Throwable {
        M3Automaton dfa = dfa();
        int[] states = ints("step.states", dfa.getNumStates());
        int[] labels = ints("step.labels", LABELS + 2);
        for (int k = 0; k < OPS; k++) labels[k] += 'a' - 1;
        long reference = 0;
        for (int k = 0; k < OPS; k++) {
            int dest = -1;
            for (int[] t : AutomatonOracle.transitions(dfa, states[k])) if (t[1] <= labels[k] && labels[k] <= t[2]) dest = t[0];
            reference += dest;
        }
        long expected = reference;
        return M3AtomPerf.checkedBatch(OPS, expected, () -> {
            long sum = 0;
            try {
                for (int i = 0; i < OPS; i++) {
                    sum += (int) STEP.invokeExact(dfa, states[i], labels[i]);
                }
            } catch (Throwable t) {
                throw new AssertionError(t);
            }
            return sum;
        });
    }

